/**
 * @description
 * 本脚本用于 n8n 的 "Code" 节点。
 * 功能：接收一个包含 XML/HTML 风格标签的文章内容，将其转换为 Hugo 静态网站生成器所需的 Markdown 文件格式。
 * 这个版本使用正则表达式解析标签，并增加了调试日志。
 *
 * 输入：上一个节点传递过来的数据项，其中应包含一个名为 `content` 的字段。
 *
 * 输出：一个包含三部分的新对象：
 * 1. `title`: 提取出的文章标题。
 * 2. `hugoArticle`: 格式化后的完整 Hugo 文章字符串。
 * 3. `fileName`: 根据文章标题建议的文件名。
 */

// --- 1. 数据准备 ---

const rawContentString = $json.content;

if (!rawContentString || typeof rawContentString !== 'string') {
  throw new Error("输入字段 'content' 为空或不是字符串，无法继续。");
}

// --- 2. 健壮的 Tag 解析 ---

let articleData;

try {
  /**
   * [已升级] 辅助函数，用于从给定的标签中安全地提取内容。
   * @param {string} tagName - 要提取的标签名 (例如 'title').
   * @param {string} content - 包含所有标签的原始字符串。
   * @returns {string} 提取到的内容，如果找不到则返回空字符串。
   */
  const extractFromTag = (tagName, content) => {
    // [升级] 这个正则表达式现在可以处理标签中的属性，例如 <article class="main">
    const regex = new RegExp(`<${tagName}[^>]*>([\\s\\S]*?)<\\/${tagName}>`, 'is');
    const match = content.match(regex);
    return match && match[1] ? match[1].trim() : '';
  };

  // 使用新的标签格式提取所有字段
  const title = extractFromTag('title', rawContentString);
  const article_content = extractFromTag('article_content', rawContentString);
  const summary = extractFromTag('summary', rawContentString);
  const tagsString = extractFromTag('tags', rawContentString);
  const mainTopicsString = extractFromTag('main_topics', rawContentString);

  // [新增] 调试日志：输出提取到的核心内容，方便排查问题。
  console.log("提取到的标题 (Title):", title);
  console.log("提取到的文章内容 (Article Content) 的前50个字符:", article_content.substring(0, 50));

  // 处理标签和主题：将逗号分隔的字符串拆分为数组，并过滤掉空值。
  const tags = tagsString ? tagsString.split(',').map(tag => tag.trim()).filter(Boolean) : [];
  const main_topics = mainTopicsString ? mainTopicsString.split(',').map(topic => topic.trim()).filter(Boolean) : [];

  // 组装数据对象
  articleData = {
    title,
    summary,
    tags,
    main_topics,
    article_content,
  };

} catch (e) {
  console.error("解析 Tag 格式内容失败:", e);
  throw new Error(`Tag 解析失败: ${e.message}.`);
}

// --- 3. 提取并验证内容 ---

const {
  title,
  summary,
  tags,
  main_topics,
  article_content
} = articleData;

// 确保核心内容存在
if (!title || !article_content) {
  // 如果内容为空，这个错误会在输出中明确提示，并终止执行
  throw new Error("解析后的数据缺少必要的 <title> 或 <article_content> 内容。请检查上游节点的输出和本节点的日志。");
}

// --- 4. 构建 Hugo Front Matter (YAML 格式) ---

const getISODateWithTimezone = (date) => {
    const pad = (num) => (num < 10 ? '0' : '') + num;
    const offset = -date.getTimezoneOffset();
    const sign = offset >= 0 ? '+' : '-';
    const hours = pad(Math.floor(Math.abs(offset) / 60));
    const minutes = pad(Math.abs(offset) % 60);
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}${sign}${hours}:${minutes}`;
};
const hugoDate = getISODateWithTimezone(new Date());

const toYamlString = (value) => JSON.stringify(value);

const toYamlList = (arr) => {
    if (!Array.isArray(arr) || arr.length === 0) return '[]'; // 如果是空数组，输出YAML空数组
    return '\n' + arr.map(item => `  - ${toYamlString(item)}`).join('\n');
}

const frontMatter = `---
title: ${toYamlString(title)}
date: ${hugoDate}
draft: false
summary: ${toYamlString(summary || '')}
tags: ${toYamlList(tags)}
main_topics: ${toYamlList(main_topics)}
---
`;

// --- 5. 组合并返回最终结果 ---

const hugoArticle = frontMatter + '\n' + article_content;

const generateSlug = (str) =>
  str
    .toString()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim()
    .replace(/\s+/g, '-')
    .replace(/[^\w-]+/g, '')
    .replace(/--+/g, '-');

// [升级] 返回的对象中也包含了 title，方便后续节点（如Commit Message）使用。
return {
  json: {
    title: title,
    hugo_article: hugoArticle,
    fileName: `${generateSlug(title)}.md`
  }
};

/**
 * 更新单篇文章的同步状态
 * 为每篇成功同步的文章更新状态
 */
function updateSyncStatus() {
  const data = $json;

  return {
    articleId: $('生成Hugo内容').item.json.articleId,
    title: $('生成Hugo内容').item.json.title,
    fileName: $('生成Hugo内容').item.json.fileName,
    syncTime: new Date().toISOString(),
    status: 'synced_to_hugo'
  };
}

return updateSyncStatus();

/**
 * 记录同步失败的文章
 * 用于错误处理和日志记录
 */
function logSyncFailure() {
  const data = $json;

  return {
    articleId: data.articleId || $('生成Hugo内容').item.json.articleId,
    title: data.title || $('生成Hugo内容').item.json.title,
    error: data.error || data.message || '未知错误',
    timestamp: new Date().toISOString(),
    status: 'sync_failed'
  };
}

return logSyncFailure();

/**
 * @description 检查文件写入是否成功
 * 通过检查Execute Command节点的执行结果判断
 * @returns {Object} 包含成功状态和相关信息的对象
 */
function checkWriteSuccess() {
  const writeResult = $json;

  // Execute Command节点成功时会返回执行信息
  const success = writeResult && (writeResult.exitCode === 0 || writeResult.exitCode === undefined);

  return {
    success: success,
    fileName: $('生成Hugo内容1').item.json.fileName,
    articleId: $('生成Hugo内容1').item.json.articleId,
    title: $('生成Hugo内容1').item.json.title,
    filePath: `/app/hugo/hugo/content/articles/${$('生成Hugo内容1').item.json.fileName}`,
    error: success ? null : '文件写入失败',
    exitCode: writeResult.exitCode || 0
  };
}

return checkWriteSuccess();

